#include <bits/stdc++.h>
#include <unistd.h>
#include <sys/syscall.h>
using namespace std;

// A plain function call stays in user mode: a few nanoseconds.
__attribute__((noinline)) long plain(long x) { asm volatile(""); return x + 1; }

int main() {
    const int N = 1000000;
    using clk = chrono::steady_clock;
    long s = 0;
    auto t0 = clk::now();
    for (int i = 0; i < N; i++) s += plain(i);
    auto t1 = clk::now();
    // syscall(SYS_getpid) really enters the kernel (not cached by libc)
    for (int i = 0; i < N; i++) s += syscall(SYS_getpid) & 1;
    auto t2 = clk::now();
    double fn = chrono::duration<double, nano>(t1 - t0).count() / N;
    double sc = chrono::duration<double, nano>(t2 - t1).count() / N;
    printf("calls: %d (checksum %ld)\n", N, s > 0);
    printf("function call: %.1f ns each\n", fn);
    printf("system call:   %.1f ns each\n", sc);
    printf("syscall is %s than a function call\n", sc > fn ? "slower" : "not slower");
    // Cost: O(1) per call, but the syscall adds a mode switch and cache/TLB pollution.
}

