# Interrupt vector table: the CPU indexes an array with the vector number.
log = []

def divide_error():  log.append("handler 0: divide error (fault)")
def page_fault():    log.append("handler 14: page fault (fault)")
def timer():         log.append("handler 32: timer tick (interrupt)")
def keyboard():      log.append("handler 33: keyboard (interrupt)")
def syscall():       log.append("handler 128: system call (trap)")
def spurious():      log.append("unhandled vector")

idt = [spurious] * 256          # the table the OS fills at boot
idt[0], idt[14], idt[32], idt[33], idt[128] = divide_error, page_fault, timer, keyboard, syscall

def cpu_deliver(vector):
    # real CPU: push old state, switch to kernel mode, jump to idt[vector], iret
    saved_state = "saved"
    idt[vector]()               # O(1) lookup, no searching
    return saved_state

events = [32, 14, 33, 128, 0, 200]
print("incoming vectors:", events)
for v in events:
    cpu_deliver(v)
print("\n".join(log))
